<div class="pack-variant-row" data-variant-row><input type="hidden" name="variants[{{ $index }}][id]" value="{{ $variant->id??'' }}"><label>Pack size<input name="variants[{{ $index }}][label]" value="{{ $variant->label??'' }}" maxlength="40" required placeholder="e.g. 100 g"></label><label>Selling price (INR)<input type="number" name="variants[{{ $index }}][price]" value="{{ isset($variant->price)?number_format($variant->price/100,2,'.',''):'' }}" min="1" max="100000" step="0.01" required placeholder="e.g. 699"></label><label>MRP (INR)<input type="number" name="variants[{{ $index }}][compare_price]" value="{{ isset($variant->compare_price)?number_format($variant->compare_price/100,2,'.',''):'' }}" min="1" max="100000" step="0.01" placeholder="e.g. 799"></label><label>Stock<input type="number" name="variants[{{ $index }}][stock]" value="{{ $variant->stock??0 }}" min="0" max="100000" step="1" required placeholder="e.g. 25"></label><button type="button" class="table-button" data-remove-pack>Remove size</button></div>
